/**
 * Tenant shell: resolves the `Actor`, builds the flag snapshot and renders the
 * sidebar.
 *
 * Owner D. Everything below this layout can assume three invariants: an actor
 * exists, it belongs to this organization, and the flag snapshot was evaluated
 * against that organization's plan. `assertOrgScope()` is what turns the third
 * assumption into a guarantee.
 *
 * Must call (do not reimplement): resolveActorForOrg, snapshotFlags,
 * assertOrgScope
 */

import { notFound } from "next/navigation";
import type { ReactNode } from "react";
import type { LimitedResource } from "@/types/billing";
import { snapshotFlags } from "@/lib/feature-flags";
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { checkLimit } from "@/server/services/billing-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listNotifications } from "@/server/services/notification-service";
import { resolveOrgBySlug } from "@/server/services/organization-service";
import { listProjects } from "@/server/services/project-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { DashboardShell } from "./_components/dashboard-shell";
import { OrgProvider } from "./_components/org-provider";
import { UnauthorizedActionError } from "@/actions/_lib/action-errors";

type LayoutParams = { orgSlug: string };

export const dynamic = "force-dynamic";

const SIDEBAR_PROJECT_LIMIT = 12;

/** The quota dimensions the shell's usage meters read. */
const SHELL_LIMIT_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
];

export default async function Layout(props: {
  children: ReactNode;
  panel?: ReactNode;
  params: Promise<LayoutParams>;
}) {
  // Next.js 16: params is a Promise and MUST be awaited.
  const { orgSlug } = await props.params;

  const principal = await getSessionPrincipal();
  if (principal === null) {
    throw new UnauthorizedActionError();
  }

  const org = await resolveOrgBySlug(orgSlug);
  if (org === null) {
    notFound();
  }

  // A membership the caller does not have resolves to null, which is the same
  // 404 as an org that does not exist — see `_lib/tenant-context.ts`.
  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) {
    notFound();
  }
  assertOrgScope(actor, org.id);

  const flags = snapshotFlags(buildFlagContext(actor, org));

  const [projects, notifications, limitChecks] = await Promise.all([
    listProjects(actor, { orgId: org.id, limit: SIDEBAR_PROJECT_LIMIT }),
    listNotifications(actor, {
      orgId: org.id,
      recipientId: actor.userId,
      unreadOnly: true,
      limit: 1,
    }),
    // Evaluated once per navigation so `usePlanLimits()` in the client tree
    // reads a real measurement instead of falling back to "no data".
    Promise.all(
      SHELL_LIMIT_RESOURCES.map((resource) => checkLimit(org.id, resource, 0)),
    ),
  ]);

  return (
    <OrgProvider
      org={org}
      actor={actor}
      flags={flags}
      limitChecks={limitChecks}
    >
      <DashboardShell
        org={org}
        actor={actor}
        flags={flags}
        projects={projects.items.map((row) => row.project)}
        unreadCount={notifications.total}
        pathname={`/${orgSlug}`}
        panel={props.panel}
      >
        {props.children}
      </DashboardShell>
    </OrgProvider>
  );
}
/**
 * Loads the three things every page under `[orgSlug]` needs: the organization,
 * the caller's `Actor` inside it, and the feature-flag snapshot.
 *
 * Owner D. Private to the tenant subtree. It exists so that no page has to
 * remember the order of operations — resolve the org, resolve the actor, assert
 * they agree, only then evaluate flags. Getting that order wrong is how a page
 * ends up evaluating flags against somebody else's plan.
 */

import { notFound } from "next/navigation";
import { getActor } from "@/lib/actor";
import { snapshotFlags } from "@/lib/feature-flags";
import { assertOrgScope } from "@/lib/tenant";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { resolveOrgBySlug } from "@/server/services/organization-service";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

export type TenantContext = {
  readonly org: Organization;
  readonly actor: Actor;
  readonly flags: FeatureFlagSnapshot;
};

/**
 * A missing organization and an organization the caller cannot reach are the
 * same 404 on purpose: distinguishing them would leak which slugs exist.
 */
export async function loadTenantContext(orgSlug: string): Promise<TenantContext> {
  const org = await resolveOrgBySlug(orgSlug);
  if (org === null) {
    notFound();
  }

  const actor = await getActor(orgSlug);
  assertOrgScope(actor, org.id);

  const flags = snapshotFlags(buildFlagContext(actor, org));
  return { org, actor, flags };
}
/**
 * Resolves the request's `Actor` for a given org slug, or throws
 * `unauthorized` / `forbidden`. Every Server Action starts here.
 *
 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
 * this module is the seam between "there is an HTTP request with a cookie"
 * and the rest of the app, which knows nothing about requests.
 */
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { findOrgById } from "@/server/repositories/organization-repository";
import { resolveActorForOrg } from "@/server/services/session-service";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
export class UnauthorizedError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedError";
  }
}

/** Thrown when the session is valid but has no membership in the target org. */
export class NoMembershipError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly orgSlug: string) {
    super(`You are not a member of "${orgSlug}".`);
    this.name = "NoMembershipError";
  }
}

/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
export async function getActor(orgSlug: string): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();

  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) throw new NoMembershipError(orgSlug);

  return actor;
}

/** Non-throwing variant, for layouts that render a signed-out state. */
export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
  try {
    return await getActor(orgSlug);
  } catch (error) {
    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
      return null;
    }
    throw error;
  }
}

/**
 * The `Actor` for an org already identified by id — used by Route Handlers
 * that receive an `orgId` in the payload rather than a slug in the path. The
 * session's active org must match, which `assertOrgScope()` enforces.
 *
 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
 * with a single repository lookup rather than by widening that signature —
 * the slug is the only handle the session layer knows.
 */
export async function requireActorFor(orgId: OrgId): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();
  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);

  const org = await findOrgById(orgId);
  if (org === null) throw new NoMembershipError(orgId);

  const actor = await resolveActorForOrg(principal, org.slug);
  if (actor === null) throw new NoMembershipError(org.slug);

  assertOrgScope(actor, orgId);
  return actor;
}
import type { OrgId, TenantScoped } from "@/types/common";
import type { Actor } from "@/types/member";

/**
 * Multi-tenancy invariant helpers.
 *
 * Every repository query must be filtered by `org_id`, and every row that
 * crosses a service boundary must be re-checked against the actor's org. These
 * helpers are the only sanctioned way to express that — a hand-written
 * `if (row.orgId !== actor.orgId)` is a review failure.
 */

export class TenantScopeError extends Error {
  readonly code = "tenant_scope_violation" as const;

  constructor(
    readonly expectedOrgId: OrgId,
    readonly actualOrgId: OrgId,
  ) {
    super(
      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
    );
    this.name = "TenantScopeError";
  }
}

/** Throws unless `orgId` belongs to the actor's organization. */
export function assertOrgScope(actor: Actor, orgId: OrgId): void {
  if (actor.orgId !== orgId) {
    throw new TenantScopeError(actor.orgId, orgId);
  }
}

/** Throws unless every supplied row belongs to the actor's organization. */
export function assertRowsInScope<T extends TenantScoped>(
  actor: Actor,
  rows: readonly T[],
): void {
  for (const row of rows) {
    assertOrgScope(actor, row.orgId);
  }
}

/** Non-throwing predicate, for filtering rather than failing. */
export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
  return row.orgId === actor.orgId;
}

/** Narrows a nullable row to one the actor may see; `null` otherwise. */
export function scopedOrNull<T extends TenantScoped>(
  actor: Actor,
  row: T | null | undefined,
): T | null {
  if (!row) return null;
  return row.orgId === actor.orgId ? row : null;
}

/**
 * Wraps an arbitrary filter object with the actor's `orgId`, so repositories
 * cannot forget it. Always spread the caller filter first.
 */
export function withOrgScope<T extends object>(
  actor: Actor,
  filter: T,
): T & { orgId: OrgId } {
  return { ...filter, orgId: actor.orgId };
}
