"use server";

/**
 * Updates org profile and settings.
 *
 * Owner D. `settings` is a partial patch — the service merges it over the
 * stored `OrganizationSettings` so a form that only touches `digestHourUtc`
 * cannot silently clear the flag overrides.
 *
 * Must call (do not reimplement): updateOrganizationSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  updateOrganizationSchema,
  type UpdateOrganizationInput,
} from "@/schemas/organization";
import { updateOrganization } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";

const run = withAction<typeof updateOrganizationSchema, Organization>(
  updateOrganizationSchema,
  async (raw, actor) => {
    const input = raw as UpdateOrganizationInput;

    if (!can(actor, "org:update", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:update");
    }

    const organization = await updateOrganization(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return organization;
  },
  { revalidate: ["organization"], cacheProfile: "minutes" },
);

export async function updateOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  return run(raw);
}
import { describe, expect, it } from "vitest";
import {
  InvalidSlugError,
  SLUG_MAX_LENGTH,
  assertValidSlug,
  isReservedSlug,
  isValidSlug,
  projectKeyFromName,
  slugify,
  uniqueSlug,
} from "@/lib/slug";

describe("slugify", () => {
  it("lowercases, strips punctuation and collapses separators", () => {
    expect(slugify("Taskflow Core Team")).toBe("taskflow-core-team");
    expect(slugify("  Hello,   World!  ")).toBe("hello-world");
    expect(slugify("a---b")).toBe("a-b");
  });

  it("strips diacritics rather than dropping the letter", () => {
    expect(slugify("Café Münster")).toBe("cafe-munster");
  });

  it("never emits a leading or trailing hyphen", () => {
    expect(slugify("--edge--")).toBe("edge");
    expect(slugify("!!!")).toBe("");
  });

  it("respects the maximum length", () => {
    expect(slugify("x".repeat(200)).length).toBeLessThanOrEqual(SLUG_MAX_LENGTH);
  });
});

describe("slug validation", () => {
  it("accepts well-formed slugs and rejects malformed ones", () => {
    expect(isValidSlug("acme-corp")).toBe(true);
    expect(isValidSlug("a")).toBe(false);
    expect(isValidSlug("Acme")).toBe(false);
    expect(isValidSlug("acme--corp")).toBe(false);
    expect(isValidSlug("-acme")).toBe(false);
  });

  it("knows the reserved slugs", () => {
    expect(isReservedSlug("settings")).toBe(true);
    expect(isReservedSlug("acme")).toBe(false);
  });

  it("assertValidSlug throws InvalidSlugError for malformed and reserved values", () => {
    expect(() => assertValidSlug("acme-corp")).not.toThrow();
    expect(() => assertValidSlug("Acme")).toThrow(InvalidSlugError);
    expect(() => assertValidSlug("billing")).toThrow(InvalidSlugError);
  });
});

describe("uniqueSlug", () => {
  it("returns the base slug when it is free", () => {
    expect(uniqueSlug("Acme Corp", [])).toBe("acme-corp");
  });

  it("appends an incrementing suffix on collision", () => {
    expect(uniqueSlug("Acme Corp", ["acme-corp"])).toBe("acme-corp-2");
    expect(uniqueSlug("Acme Corp", ["acme-corp", "acme-corp-2"])).toBe("acme-corp-3");
  });

