import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("$P/tests/server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { InvalidSlugError } from "@/lib/slug";
import { PermissionDeniedError } from "@/lib/permissions";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { activityActionSchema, activityFilterSchema } from "@/schemas/activity";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import * as orgRepo from "@/server/repositories/organization-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
afterEach(() => { vi.useRealTimers(); });

const DAY = 24 * 60 * 60 * 1000;

describe("rename", () => {
  it("renames, retires, holds, releases", async () => {
    const t0 = new Date("2027-01-01T00:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(t0);
    const a = await createTenant("alpha");
    const b = await createTenant("beta");
    const events: unknown[] = [];
    const off = subscribe("organization.slug_changed", (p) => { events.push(p); });

    const before = await orgRepo.findOrgById(a.org.id);
    const renamed = await orgService.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "alpha-new" });
    expect(renamed.slug).toBe("alpha-new");
    expect(renamed).toEqual({ ...before, slug: "alpha-new" });
    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({ orgId: a.org.id, actorId: a.userIds.admin, from: "alpha", to: "alpha-new" });

    const acts = await listActivity(a.actors.admin, { orgId: a.org.id, action: ["organization.slug_changed"], limit: 25, cursor: null });
    expect(acts.items).toHaveLength(1);
    expect(acts.items[0]).toMatchObject({ subjectKind: "organization", subjectId: a.org.id, metadata: { from: "alpha", to: "alpha-new" }, actorId: a.userIds.admin });

    // reads
    expect((await orgService.getOrganizationSummary(a.actors.member, a.org.id)).organization.slug).toBe("alpha-new");
    expect((await orgService.listOrganizationsForUser(a.userIds.owner)).map((o) => o.slug)).toEqual(["alpha-new"]);
    expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
    expect((await orgService.resolveOrgBySlug("alpha-new"))?.id).toBe(a.org.id);
    const principal = { userId: a.userIds.member, email: "x", activeOrgId: null, expiresAt: "2099-01-01T00:00:00.000Z" } as never;
    expect((await sessionService.resolveActorForOrg(principal, "alpha"))?.orgId).toBe(a.org.id);
    expect((await sessionService.resolveActorForOrg(principal, "alpha-new"))?.orgId).toBe(a.org.id);

    // held: others refused, creation suffixed
    await expect(orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha" })).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha-new" })).rejects.toBeInstanceOf(InvalidSlugError);
    expect(await orgRepo.listTakenOrgSlugs("alpha")).toEqual(expect.arrayContaining(["alpha", "alpha-new"]));

    // no-op
    events.length = 0;
    const same = await orgService.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "alpha-new" });
    expect(same).toEqual(renamed);
    expect(events).toHaveLength(0);

    // permission
    await expect(orgService.renameOrganizationSlug(a.actors.member, { orgId: a.org.id, slug: "zzz" })).rejects.toBeInstanceOf(PermissionDeniedError);
    // invalid / reserved
    await expect(orgService.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "Bad Slug" })).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(orgService.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "settings" })).rejects.toBeInstanceOf(InvalidSlugError);
    expect((await orgRepo.findOrgById(a.org.id))?.slug).toBe("alpha-new");

    // chain at t0 + 10d
    vi.setSystemTime(new Date(t0.getTime() + 10 * DAY));
    await orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "alpha-third" });
    expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
    expect((await orgService.resolveOrgBySlug("alpha-new"))?.id).toBe(a.org.id);

    // just before alpha's hold ends
    vi.setSystemTime(new Date(t0.getTime() + ORG_SLUG_HOLD_DAYS * DAY - 1));
    expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
    await expect(orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha" })).rejects.toBeInstanceOf(InvalidSlugError);

    // exactly at end
    vi.setSystemTime(new Date(t0.getTime() + ORG_SLUG_HOLD_DAYS * DAY));
    expect(await orgService.resolveOrgBySlug("alpha")).toBeNull();
    expect(await orgRepo.findOrgBySlug("alpha")).toBeNull();
    expect(await sessionService.resolveActorForOrg(principal, "alpha")).toBeNull();
    expect((await orgService.resolveOrgBySlug("alpha-new"))?.id).toBe(a.org.id);
    expect(await orgRepo.listTakenOrgSlugs("alpha")).not.toContain("alpha");

    // rename back to own retired slug (alpha-new still held)
    await orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "alpha-new" });
    expect((await orgService.resolveOrgBySlug("alpha-third"))?.id).toBe(a.org.id);
    // b may now take "alpha"
    const bRenamed = await orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha" });
    expect(bRenamed.slug).toBe("alpha");
    expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(b.org.id);
    // beta retired by b, held
    const created = await orgService.createOrganization(a.userIds.owner, { name: "Beta again", slug: "beta", plan: "free" });
    expect(created.slug).toBe("beta-2");
    off();
  });

  it("schemas accept the action", () => {
    expect(activityActionSchema.parse("organization.slug_changed")).toBe("organization.slug_changed");
  });

  it("records once with listeners attached", async () => {
    const detach = registerActivityListeners();
    const c = await createTenant("gamma");
    await orgService.renameOrganizationSlug(c.actors.owner, { orgId: c.org.id, slug: "gamma-two" });
    const acts = await listActivity(c.actors.admin, { orgId: c.org.id, action: ["organization.slug_changed"], limit: 25, cursor: null });
    expect(acts.items).toHaveLength(1);
    detach();
  });
});
