 * `ORG_SLUG_HOLD_DAYS`. Renaming to the current slug is a no-op.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug === input.slug) return org;

  assertValidSlug(input.slug);

  const holder = await orgRepo.findOrgSlugHolder(input.slug);
  if (holder !== null && holder !== org.id) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const renamed = await orgRepo.renameOrgSlug(org.id, input.slug);

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: org.slug,
    to: renamed.slug,
  });

  // Audited here, like every other settings change, rather than by an
  // activity listener — one rename, one audit row.
  await record(org.id, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: renamed.id,
    projectId: null,
    summary: `Workspace URL /${org.slug} → /${renamed.slug}`,
    metadata: { from: org.slug, to: renamed.slug },
  });

  return renamed;
}

